ALTER TABLE users ADD COLUMN IF NOT EXISTS tenant_id VARCHAR(80);ALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash TEXT;ALTER TABLE users ALTER COLUMN password DROP NOT NULL;UPDATE users SET tenant_id='default' WHERE tenant_id IS NULL;ALTER TABLE users ALTER COLUMN tenant_id SET DEFAULT 'default';ALTER TABLE users ALTER COLUMN tenant_id SET NOT NULL;
CREATE TABLE IF NOT EXISTS governed_field_observations(id BIGSERIAL PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,site_key VARCHAR(80) NOT NULL,colony_key VARCHAR(80) NOT NULL,intervention_type VARCHAR(80) NOT NULL,survey_id VARCHAR(120) NOT NULL,source_record_id VARCHAR(160) NOT NULL,source_sha256 CHAR(64) NOT NULL,image_sha256 CHAR(64) NOT NULL,dataset_version VARCHAR(80) NOT NULL,model_version VARCHAR(80) NOT NULL,device_id VARCHAR(120) NOT NULL,species_taxon VARCHAR(160) NOT NULL,health_class VARCHAR(30) NOT NULL,survival_status VARCHAR(20) NOT NULL,initial_size_cm NUMERIC(12,3),current_size_cm NUMERIC(12,3),growth_cm NUMERIC(12,3),missing_reason TEXT,latitude NUMERIC(9,6) NOT NULL,longitude NUMERIC(9,6) NOT NULL,accuracy_m NUMERIC(10,2) NOT NULL,captured_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,season VARCHAR(40) NOT NULL,review_status VARCHAR(20) NOT NULL DEFAULT 'pending',collected_by INTEGER NOT NULL REFERENCES users(id),UNIQUE(tenant_id,source_record_id));
CREATE TABLE IF NOT EXISTS fieldwork_scientist_reviews(id BIGSERIAL PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,observation_id BIGINT NOT NULL REFERENCES governed_field_observations(id),decision VARCHAR(20) NOT NULL CHECK(decision IN('accepted','rejected')),rationale TEXT NOT NULL,reviewer_user_id INTEGER NOT NULL REFERENCES users(id),reviewed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,observation_id));
CREATE TABLE IF NOT EXISTS fieldwork_events(id BIGSERIAL PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,observation_id BIGINT NOT NULL REFERENCES governed_field_observations(id),event_type VARCHAR(80) NOT NULL,actor_user_id INTEGER NOT NULL REFERENCES users(id),payload JSONB NOT NULL,previous_hash CHAR(64),event_hash CHAR(64) NOT NULL UNIQUE,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS fieldwork_tenant_idx ON governed_field_observations(tenant_id,site_key,id);CREATE INDEX IF NOT EXISTS fieldwork_events_idx ON fieldwork_events(tenant_id,observation_id,id);
CREATE OR REPLACE FUNCTION prevent_fieldwork_event_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'fieldwork_events is append-only';END;$$ LANGUAGE plpgsql;DROP TRIGGER IF EXISTS fieldwork_events_immutable ON fieldwork_events;CREATE TRIGGER fieldwork_events_immutable BEFORE UPDATE OR DELETE ON fieldwork_events FOR EACH ROW EXECUTE FUNCTION prevent_fieldwork_event_mutation();
